package crypto.ratelimit

import java.security.SecureRandom
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}

object Constants {
  val GCM_TAG_BITS = 128
  val GCM_NONCE_BYTES = 12
  val MAX_RETRIES = 3
  val RATE_LIMIT_WINDOW_MS = 60000L
  val MAX_REQUESTS_PER_WINDOW = 100
  val MAX_PLAINTEXT_CHUNKS = 1024
  val CHUNK_SIZE = 4096
}

class RateLimiter {
  private val windowStart = new AtomicLong(System.currentTimeMillis())
  private val requestCount = new AtomicInteger(0)

  def tryAcquire(): Boolean = {
    val now = System.currentTimeMillis()
    if (now - windowStart.get() > Constants.RATE_LIMIT_WINDOW_MS) {
      windowStart.set(now)
      requestCount.set(0)
    }
    requestCount.incrementAndGet() <= Constants.MAX_REQUESTS_PER_WINDOW
  }
}

class CryptoProcessor(key: Array[Byte]) {
  require(key.length == 32, "Key must be 256 bits")
  private val secureRandom = new SecureRandom()
  private val rateLimiter = new RateLimiter()

  private def generateNonce(): Array[Byte] = {
    val nonce = new Array[Byte](Constants.GCM_NONCE_BYTES)
    secureRandom.nextBytes(nonce)
    nonce
  }

  /**
   * Computes the total buffer size needed for encrypting chunked data.
   * Each chunk produces CHUNK_SIZE + GCM_TAG_BITS/8 bytes of ciphertext.
   * We also prepend the nonce.
   */
  private def computeOutputSize(numChunks: Int): Int = {
    val perChunkOverhead = Constants.GCM_TAG_BITS / 8  // 16 bytes
    val chunkOutputSize = Constants.CHUNK_SIZE + perChunkOverhead  // 4112
    val nonceSize = Constants.GCM_NONCE_BYTES  // 12
    // Total: nonce + numChunks * chunkOutputSize
    val totalPayload = numChunks * chunkOutputSize  // potential Int overflow
    nonceSize + totalPayload
  }

  private def validateChunkCount(numChunks: Int): Boolean = {
    // Ensure we don't exceed maximum chunks
    numChunks > 0 && numChunks <= Constants.MAX_PLAINTEXT_CHUNKS
  }

  def encryptChunked(plaintext: Array[Byte], retryCount: Int = 0): Either[String, Array[Byte]] = {
    if (!rateLimiter.tryAcquire()) {
      if (retryCount < Constants.MAX_RETRIES) {
        Thread.sleep(100L * (retryCount + 1))
        return encryptChunked(plaintext, retryCount + 1)
      }
      return Left("Rate limit exceeded after retries")
    }

    val numChunks = computeChunkCount(plaintext.length)
    if (!validateChunkCount(numChunks)) {
      return Left(s"Invalid chunk count: $numChunks")
    }

    val outputSize = computeOutputSize(numChunks)
    if (outputSize <= 0) {
      return Left("Invalid output size computation")
    }

    try {
      val nonce = generateNonce()
      val keySpec = new SecretKeySpec(key, "AES")
      val output = new Array[Byte](outputSize)
      System.arraycopy(nonce, 0, output, 0, nonce.length)

      var offset = Constants.GCM_NONCE_BYTES
      var srcOffset = 0

      for (i <- 0 until numChunks) {
        val chunkLen = math.min(Constants.CHUNK_SIZE, plaintext.length - srcOffset)
        val chunk = plaintext.slice(srcOffset, srcOffset + chunkLen)

        val chunkNonce = deriveChunkNonce(nonce, i)
        val gcmSpec = new GCMParameterSpec(Constants.GCM_TAG_BITS, chunkNonce)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)

        val encrypted = cipher.doFinal(chunk)
        System.arraycopy(encrypted, 0, output, offset, encrypted.length)
        offset += encrypted.length
        srcOffset += chunkLen
      }

      Right(output.take(offset))
    } catch {
      case e: Exception =>
        if (retryCount < Constants.MAX_RETRIES) {
          encryptChunked(plaintext, retryCount + 1)
        } else {
          Left(s"Encryption failed: ${e.getMessage}")
        }
    }
  }

  private def computeChunkCount(dataLength: Int): Int = {
    (dataLength + Constants.CHUNK_SIZE - 1) / Constants.CHUNK_SIZE
  }

  private def deriveChunkNonce(baseNonce: Array[Byte], chunkIndex: Int): Array[Byte] = {
    val derived = baseNonce.clone()
    // XOR chunk index into last 4 bytes of nonce
    derived(8) = (derived(8) ^ ((chunkIndex >> 24) & 0xFF)).toByte
    derived(9) = (derived(9) ^ ((chunkIndex >> 16) & 0xFF)).toByte
    derived(10) = (derived(10) ^ ((chunkIndex >> 8) & 0xFF)).toByte
    derived(11) = (derived(11) ^ (chunkIndex & 0xFF)).toByte
    derived
  }

  /**
   * Streaming decryption that processes externally-specified chunk parameters.
   * Used when receiving data from a remote peer that specifies its own chunking.
   */
  def decryptWithPeerChunking(
    ciphertext: Array[Byte],
    peerChunkCount: Int,
    peerChunkSize: Int
  ): Either[String, Array[Byte]] = {
    if (!rateLimiter.tryAcquire()) {
      return Left("Rate limit exceeded")
    }

    // Validate peer parameters
    if (peerChunkCount <= 0 || peerChunkSize <= 0) {
      return Left("Invalid peer parameters")
    }
    if (peerChunkCount > Constants.MAX_PLAINTEXT_CHUNKS) {
      return Left("Peer chunk count exceeds maximum")
    }
    if (peerChunkSize > Constants.CHUNK_SIZE) {
      return Left("Peer chunk size exceeds maximum")
    }

    // Compute expected ciphertext size from peer's parameters
    val tagSize = Constants.GCM_TAG_BITS / 8
    val expectedPayloadSize = peerChunkCount * (peerChunkSize + tagSize)
    val expectedTotalSize = Constants.GCM_NONCE_BYTES + expectedPayloadSize

    // Validate ciphertext length matches expected
    if (ciphertext.length != expectedTotalSize) {
      return Left("Ciphertext length mismatch")
    }

    // Allocate output buffer for decrypted plaintext
    val outputBufferSize = peerChunkCount * peerChunkSize
    if (outputBufferSize <= 0) {
      return Left("Invalid output buffer computation")
    }

    try {
      val nonce = ciphertext.take(Constants.GCM_NONCE_BYTES)
      val keySpec = new SecretKeySpec(key, "AES")
      val output = new Array[Byte](outputBufferSize)
      var readOffset = Constants.GCM_NONCE_BYTES
      var writeOffset = 0

      for (i <- 0 until peerChunkCount) {
        val chunkCipherLen = peerChunkSize + tagSize
        val chunkData = ciphertext.slice(readOffset, readOffset + chunkCipherLen)

        val chunkNonce = deriveChunkNonce(nonce, i)
        val gcmSpec = new GCMParameterSpec(Constants.GCM_TAG_BITS, chunkNonce)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)

        val decrypted = cipher.doFinal(chunkData)
        System.arraycopy(decrypted, 0, output, writeOffset, decrypted.length)
        writeOffset += decrypted.length
        readOffset += chunkCipherLen
      }

      Right(output.take(writeOffset))
    } catch {
      case e: Exception => Left(s"Decryption failed: ${e.getMessage}")
    }
  }
}
